package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;import java.util.concurrent.atomic.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
class SharedWriteLockTelemetryTest {
 DataSource source;JdbcTemplate jdbc;TransactionTemplate tx;
 DataSource source(){var value=new org.h2.jdbcx.JdbcDataSource();value.setURL("jdbc:h2:mem:fictional-native-lock-"+System.nanoTime()+";MODE=MySQL;DB_CLOSE_DELAY=-1");return value;}
 @BeforeEach void setup(){source=source();jdbc=new JdbcTemplate(source);jdbc.execute("CREATE TABLE IF NOT EXISTS worker_lock(id INT PRIMARY KEY)");if(jdbc.queryForObject("SELECT COUNT(*) FROM worker_lock WHERE id=1",Integer.class)==0)jdbc.update("INSERT INTO worker_lock VALUES(1)");assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM worker_lock",Integer.class));tx=new TransactionTemplate(new DataSourceTransactionManager(source));}
 @Test void actualEntrySqlMeasuresExactlyItsQueryAndOuterTransactionGuardDoesNotEmit(){var nanos=new AtomicLong(10);var observed=new AtomicLong(-9);var calls=new AtomicInteger();var entry=new JdbcSharedWriteEntry(source,()->nanos.getAndAdd(100000000),value->{observed.set(value);calls.incrementAndGet();});assertThrows(IllegalStateException.class,entry::lock);assertEquals(0,calls.get());tx.execute(s->{entry.lock();return null;});assertEquals(1,calls.get());assertEquals(100000000,observed.get());}
 @Test void originalSqlFailureStillMeasuresWaitAndRollsBack(){var nanos=new AtomicLong();var observed=new AtomicLong(-9);jdbc.update("INSERT INTO worker_lock VALUES(777)");try{var entry=new JdbcSharedWriteEntry(source,()->nanos.getAndAdd(100),observed::set);assertThrows(IllegalStateException.class,()->tx.execute(s->{entry.lock();return null;}));assertEquals(100,observed.get());}finally{jdbc.update("DELETE FROM worker_lock WHERE id=777");}}
 @Test void instrumentationFailureCannotChangeOriginalSuccessfulSqlTransaction(){var calls=new AtomicInteger();var entry=new JdbcSharedWriteEntry(source,System::nanoTime,value->{calls.incrementAndGet();throw new IllegalStateException("fictional observer unavailable");});tx.execute(s->{entry.lock();return null;});assertEquals(1,calls.get());}
 @Test void constructorMakesNoSqlAndClockFailureIsUnavailableRatherThanZero(){var cold=mock(DataSource.class);new JdbcSharedWriteEntry(cold);verifyNoInteractions(cold);var observed=new AtomicLong();var entry=new JdbcSharedWriteEntry(source,()->{throw new IllegalStateException("fictional clock unavailable");},observed::set);tx.execute(s->{entry.lock();return null;});assertEquals(-1,observed.get());}
 @Test void missingOriginalStartDoesNotBecomeAValidDurationWhenEndClockRecovers(){var calls=new AtomicInteger();var observed=new AtomicLong();var entry=new JdbcSharedWriteEntry(source,()->{if(calls.incrementAndGet()==1)throw new IllegalStateException("fictional start clock unavailable");return 123456;},observed::set);tx.execute(s->{entry.lock();return null;});assertEquals(-1,observed.get());assertEquals(1,calls.get());}

}
